[Form]
public class NDXContactPersonLookup extends FormRun implements NDXContactPersonLookupI
{
    FormStringControl callingNameControl; 
    FormStringControl callingIdControl;
    NDXContactPersonLookupResult nDXContactPersonLookupResult;

}

/// <summary>
/// PaffH 11.08.25
/// </summary>
/// <param name = "_callingNameControl">FormStringControl</param>
public void callingNameControl(FormStringControl _callingNameControl)
{
    callingNameControl = _callingNameControl;
}

/// <summary>
/// PaffH 11.08.25
/// </summary>
/// <param name = "_callingIdControl">FormStringControl</param>
public void callingIdControl(FormStringControl _callingIdControl)
{
    callingIdControl = _callingIdControl;
}

/// <summary>
/// PaffH 11.08.25
/// </summary>
/// <param name = "_selectString">str</param>
public void closeSelect(str _selectString)
{
    str selectString = _selectString;
    nDXContactPersonLookupResult.parmContract().parmStrName(DirPartyTable.Name);
    nDXContactPersonLookupResult.parmContract().parmStrId(ContactPerson.ContactPersonId);
    nDXContactPersonLookupResult.parmContract().parmStrEmail(LogisticsElectronicAddress.Locator);
    nDXContactPersonLookupResult.parmContract().parmContactPerson(ContactPerson);
    nDXContactPersonLookupResult.parmContract().parmDirPartyTableContactPerson(DirPartyTable);
    nDXContactPersonLookupResult.parmContract().parmDirPartyTableOrganisation(DirPartyTableFor);
    nDXContactPersonLookupResult.parmContract().parmStrId(ContactPerson.ContactPersonId);

    if (nDXContactPersonLookupResult.parmContract().parmLookupByEmail())
    {
        selectString = LogisticsElectronicAddress.Locator;
        callingNameControl.text(selectString);
    }
    else if (nDXContactPersonLookupResult.parmContract().parmLookupByName())
    {
        selectString = DirPartyTable.Name;
        callingNameControl.text(selectString);
    }
    else if (nDXContactPersonLookupResult.parmContract().parmLookupById() == NoYes::Yes)
    {
        selectString = ContactPerson.ContactPersonId;
        callingIdControl.text(selectString);
    }
    super(selectString);
}

/// <summary>
/// PaffH 12.08.25
/// </summary>
public void init()
{
    nDXContactPersonLookupResult = NDXContactPersonLookupResult::instance();
    super();
    if (nDXContactPersonLookupResult.parmContract().parmLookupById())
    {
        element.selectMode(ContactPerson_ContactPersonId);
    }
    else if (nDXContactPersonLookupResult.parmContract().parmLookupByName())
    {
        element.selectMode(DirPartyTable_Name);
    }
    else if (nDXContactPersonLookupResult.parmContract().parmLookupByEmail())
    {
        element.selectMode(LogisticsElectronicAddress_Locator);
    }
}

/// <summary>
/// PaffH 11.08.25
/// </summary>
public void run()
{
    ContactPerson contactPersonLocal;
    DirPartyTable dirPartyTableLocal;
    LogisticsElectronicAddress logisticsElectronicAddressLocal;
    Query q;
    super();
    nDXContactPersonLookupResult.parmContract().parmQueryValue(this.DisplayQuery());
    if (element.args().lookupValue())
    {
        str lookUpValue = element.args().lookupValue();
        if (nDXContactPersonLookupResult.parmContract().parmLookupByEmail())
        {
            lookUpValue = nDXContactPersonLookupResult.parmContract().parmStrEmail();
            q = NDXContactPersonLookupClass::queryLookupContactPersonByEmail();
            logisticsElectronicAddressLocal = NDXContactPersonLookupClass::queryRunLookupContactPersonByEmail(q, lookUpValue);
            if (!logisticsElectronicAddressLocal)
            {
                logisticsElectronicAddressLocal = NDXContactPersonLookupClass::queryRunLookupContactPersonByEmail(q, strFmt(NDXPlaceholderConstants::PlaceHolderStar, lookUpValue));
            }
            if (!logisticsElectronicAddressLocal)
            {
                logisticsElectronicAddressLocal = NDXContactPersonLookupClass::queryRunLookupContactPersonByEmail(q, strFmt(NDXPlaceholderConstants::StarPlaceHolderStar, lookUpValue));
            }
            if (logisticsElectronicAddressLocal)
            {
                LogisticsElectronicAddress_ds.positionToRecord(logisticsElectronicAddressLocal);
            }
        }
        else if (nDXContactPersonLookupResult.parmContract().parmLookupByName() == NoYes::Yes)
        {
            lookUpValue = nDXContactPersonLookupResult.parmContract().parmStrName();
            q = NDXContactPersonLookupClass::queryLookupContactPersonByName();
            dirPartyTableLocal = NDXContactPersonLookupClass::queryRunLookupContactPersonByName(q, lookUpValue);
            if (!dirPartyTableLocal)
            {
                dirPartyTableLocal = NDXContactPersonLookupClass::queryRunLookupContactPersonByName(q, strFmt(NDXPlaceholderConstants::PlaceHolderStar, lookUpValue));
            }
            if (!dirPartyTableLocal)
            {
                dirPartyTableLocal = NDXContactPersonLookupClass::queryRunLookupContactPersonByName(q, strFmt(NDXPlaceholderConstants::StarPlaceHolderStar, lookUpValue));
            }
            if (dirPartyTableLocal)
            {
                DirPartyTable_DS.positionToRecord(dirPartyTableLocal);
            }
        }
        else if (nDXContactPersonLookupResult.parmContract().parmLookupById() == NoYes::Yes)
        {
            lookUpValue = nDXContactPersonLookupResult.parmContract().parmStrId();
            q = NDXContactPersonLookupClass::queryLookupContactPersonById();
            contactPersonLocal = NDXContactPersonLookupClass::queryRunLookupContactPersonById(q, lookUpValue);
            if (!contactPersonLocal)
            {
                contactPersonLocal = NDXContactPersonLookupClass::queryRunLookupContactPersonById(q, strFmt(NDXPlaceholderConstants::PlaceHolderStar, lookUpValue));
            }
            if (contactPersonLocal)
            {
                ContactPerson_DS.positionToRecord(contactPersonLocal);
            }
        }
    }

}

/// <summary>
/// PaffH 12.08.25
/// </summary>
public void init()
{
    super();
    if (nDXContactPersonLookupResult.parmContract().parmLookupByName())
    {
        QueryBuildDataSource qbds = this.query().dataSourceName(this.name());
        qbds.addOrderByField(fieldNum(DirPartyTable, Name));
    }
}

/// <summary>
/// PaffH 11.08.25
/// display only primary address
/// </summary>
public void init()
{
    super();
    QueryBuildDataSource qbds = this.query().dataSourceName(this.name());
    qbds.addRange(fieldNum(DirPartyLocation, IsPrimary)).value(queryValue(NoYes::Yes));
}

/// <summary>
/// PaffH 11.08.25
/// display only Email
/// </summary>
public void init()
{
    super();
    QueryBuildDataSource qbds = this.query().dataSourceName(this.name());

    qbds.clearLinks();
    qbds.addLink(fieldNum(DirPerson, PrimaryContactEmail), fieldNum(LogisticsElectronicAddress, RecId), DirPerson_ds.name());

    qbds.addRange(fieldNum(LogisticsElectronicAddress, Type)).value(queryValue(LogisticsElectronicAddressMethodType::Email));

    if (nDXContactPersonLookupResult.parmContract().parmLookupByEmail())
    {
        qbds.addOrderByField(fieldNum(LogisticsElectronicAddress, Locator));
    }

}

/// <summary>
/// PaffH 11.08.25
/// </summary>
public void init()
{
    super();
    QueryBuildDataSource qbds = this.query().dataSourceName(this.name());
    qbds.clearLinks();
    qbds.addLink(fieldNum(ContactPerson, ContactForParty), fieldNum(DirPartyTable, RecId), ContactPerson_DS.name());
}

/// <summary>
/// PaffH 11.08.25
/// display only primary address
/// </summary>
public void init()
{
    super();
    QueryBuildDataSource qbds = this.query().dataSourceName(this.name());
    qbds.addRange(fieldNum(DirPartyLocation, IsPrimary)).value(queryValue(NoYes::Yes));
}
